real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector) && defined(__riscv_v)
        size_t n = LEN_1D;
        const real_t *xptr = x;
        real_t s = 0.0;

        // Use stripmining to accumulate in scalar to maintain exact same
        // accumulation order as scalar loop for correctness
        while (n > 0) {
            size_t vl = __riscv_vsetvl_e32m1(n);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(xptr, vl);
            // Reduce vector to scalar, then add to running sum
            // This matches scalar accumulation order more closely
            vfloat32m1_t vpart = __riscv_vfredusum_vs_f32m1_f32m1(vx, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
            s += __riscv_vfmv_f_s_f32m1_f32(vpart);
            xptr += vl;
            n -= vl;
        }
#else
        real_t s = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) s += x[i];
#endif
        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

