real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;
        Index_type i = 0;

#if defined(__riscv_vector)
        size_t vlmax = __riscv_vsetvlmax_e32m1();
        real_t local_scan = 0.0;

        for (; i + vlmax <= LEN_1D; i += vlmax) {
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[i], vlmax);

            // Compute prefix sums within each vector
            // v0: [x0, x1, x2, x3, ...]
            // After step 1: [x0, x0+x1, x1+x2, x2+x3, ...] - no, need proper prefix

            // Proper prefix sum using slide1up
            // v1[i] = v0[i] + v0[i-1] (with v0[-1]=0)
            vfloat32m1_t vsum = vx;

            vfloat32m1_t vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            vslide = __riscv_vfslide1up_vf_f32m1(vsum, 0.0f, vlmax);
            vsum = __riscv_vfadd_vv_f32m1(vsum, vslide, vlmax);

            // Add the running total from previous chunks to all elements
            vfloat32m1_t vy = __riscv_vfadd_vf_f32m1(vsum, local_scan, vlmax);
            __riscv_vse32_v_f32m1(&y[i], vy, vlmax);

            // Update local_scan with total of this chunk
            // The last element of vsum is the sum of all elements in this chunk
            real_t chunk_last[64];
            __riscv_vse32_v_f32m1(chunk_last, vsum, vlmax);
            local_scan += chunk_last[vlmax - 1];
        }

        scan_var = local_scan;
#endif
        // Scalar cleanup
        for (; i < LEN_1D; ++i) {
            y[i] = scan_var;
            scan_var += x[i];
        }
        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

