real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1(APPS_N1D - i);

            vfloat32m1_t x1 = __riscv_vle32_v_f32m1(&apps_x1[i], vl);
            vfloat32m1_t x2 = __riscv_vle32_v_f32m1(&apps_x2[i], vl);
            vfloat32m1_t x3 = __riscv_vle32_v_f32m1(&apps_x3[i], vl);
            vfloat32m1_t x4 = __riscv_vle32_v_f32m1(&apps_x4[i], vl);

            vfloat32m1_t y1 = __riscv_vle32_v_f32m1(&apps_y1[i], vl);
            vfloat32m1_t y2 = __riscv_vle32_v_f32m1(&apps_y2[i], vl);
            vfloat32m1_t y3 = __riscv_vle32_v_f32m1(&apps_y3[i], vl);
            vfloat32m1_t y4 = __riscv_vle32_v_f32m1(&apps_y4[i], vl);

            vfloat32m1_t fx1 = __riscv_vle32_v_f32m1(&apps_fx1[i], vl);
            vfloat32m1_t fx2 = __riscv_vle32_v_f32m1(&apps_fx2[i], vl);
            vfloat32m1_t fx3 = __riscv_vle32_v_f32m1(&apps_fx3[i], vl);
            vfloat32m1_t fx4 = __riscv_vle32_v_f32m1(&apps_fx4[i], vl);

            vfloat32m1_t fy1 = __riscv_vle32_v_f32m1(&apps_fy1[i], vl);
            vfloat32m1_t fy2 = __riscv_vle32_v_f32m1(&apps_fy2[i], vl);
            vfloat32m1_t fy3 = __riscv_vle32_v_f32m1(&apps_fy3[i], vl);
            vfloat32m1_t fy4 = __riscv_vle32_v_f32m1(&apps_fy4[i], vl);

            vfloat32m1_t x1px2 = __riscv_vfadd_vv_f32m1(x1, x2, vl);
            vfloat32m1_t x3px4 = __riscv_vfadd_vv_f32m1(x3, x4, vl);
            vfloat32m1_t xi = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(x1px2, x3px4, vl), half, vl);

            vfloat32m1_t x2px3 = __riscv_vfadd_vv_f32m1(x2, x3, vl);
            vfloat32m1_t x4px1 = __riscv_vfadd_vv_f32m1(x4, x1, vl);
            vfloat32m1_t xj = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(x2px3, x4px1, vl), half, vl);

            vfloat32m1_t y1py2 = __riscv_vfadd_vv_f32m1(y1, y2, vl);
            vfloat32m1_t y3py4 = __riscv_vfadd_vv_f32m1(y3, y4, vl);
            vfloat32m1_t yi = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(y1py2, y3py4, vl), half, vl);

            vfloat32m1_t y2py3 = __riscv_vfadd_vv_f32m1(y2, y3, vl);
            vfloat32m1_t y4py1 = __riscv_vfadd_vv_f32m1(y4, y1, vl);
            vfloat32m1_t yj = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(y2py3, y4py1, vl), half, vl);

            vfloat32m1_t fx1pfx2 = __riscv_vfadd_vv_f32m1(fx1, fx2, vl);
            vfloat32m1_t fx3pfx4 = __riscv_vfadd_vv_f32m1(fx3, fx4, vl);
            vfloat32m1_t fxi = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(fx1pfx2, fx3pfx4, vl), half, vl);

            vfloat32m1_t fx2pfx3 = __riscv_vfadd_vv_f32m1(fx2, fx3, vl);
            vfloat32m1_t fx4pfx1 = __riscv_vfadd_vv_f32m1(fx4, fx1, vl);
            vfloat32m1_t fxj = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(fx2pfx3, fx4pfx1, vl), half, vl);

            vfloat32m1_t fy1pfy2 = __riscv_vfadd_vv_f32m1(fy1, fy2, vl);
            vfloat32m1_t fy3pfy4 = __riscv_vfadd_vv_f32m1(fy3, fy4, vl);
            vfloat32m1_t fyi = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(fy1pfy2, fy3pfy4, vl), half, vl);

            vfloat32m1_t fy2pfy3 = __riscv_vfadd_vv_f32m1(fy2, fy3, vl);
            vfloat32m1_t fy4pfy1 = __riscv_vfadd_vv_f32m1(fy4, fy1, vl);
            vfloat32m1_t fyj = __riscv_vfmul_vf_f32m1(__riscv_vfsub_vv_f32m1(fy2pfy3, fy4pfy1, vl), half, vl);

            vfloat32m1_t xiyj = __riscv_vfmul_vv_f32m1(xi, yj, vl);
            vfloat32m1_t xjyi = __riscv_vfmul_vv_f32m1(xj, yi, vl);
            vfloat32m1_t denom = __riscv_vfadd_vf_f32m1(__riscv_vfsub_vv_f32m1(xiyj, xjyi, vl), ptiny, vl);
            vfloat32m1_t rarea = __riscv_vfrdiv_vf_f32m1(denom, 1.0f, vl);

            vfloat32m1_t fxiyj = __riscv_vfmul_vv_f32m1(fxi, yj, vl);
            vfloat32m1_t fxjyi = __riscv_vfmul_vv_f32m1(fxj, yi, vl);
            vfloat32m1_t dfxdx = __riscv_vfmul_vv_f32m1(rarea, __riscv_vfsub_vv_f32m1(fxiyj, fxjyi, vl), vl);

            vfloat32m1_t fyjxi = __riscv_vfmul_vv_f32m1(fyj, xi, vl);
            vfloat32m1_t fyixj = __riscv_vfmul_vv_f32m1(fyi, xj, vl);
            vfloat32m1_t dfydy = __riscv_vfmul_vv_f32m1(rarea, __riscv_vfsub_vv_f32m1(fyjxi, fyixj, vl), vl);

            vfloat32m1_t fy_sum = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(fy1, fy2, vl), __riscv_vfadd_vv_f32m1(fy3, fy4, vl), vl);
            vfloat32m1_t y_sum = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(y1, y2, vl), __riscv_vfadd_vv_f32m1(y3, y4, vl), vl);
            vfloat32m1_t affine = __riscv_vfdiv_vv_f32m1(fy_sum, y_sum, vl);

            vfloat32m1_t div = __riscv_vfadd_vv_f32m1(__riscv_vfadd_vv_f32m1(dfxdx, dfydy, vl), affine, vl);
            __riscv_vse32_v_f32m1(&apps_div[i], div, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
#endif
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

