real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
#if defined(__riscv_vector)
        // First loop: compute e_new
        {
            size_t n = APPS_N1D;
            size_t vl;
            for (size_t i = 0; i < n; i += vl) {
                vl = __riscv_vsetvl_e32m8(n - i);
                vfloat32m8_t e_old = __riscv_vle32_v_f32m8(&apps_e_old[i], vl);
                vfloat32m8_t delvc = __riscv_vle32_v_f32m8(&apps_delvc[i], vl);
                vfloat32m8_t p_old = __riscv_vle32_v_f32m8(&apps_p_old[i], vl);
                vfloat32m8_t q_old = __riscv_vle32_v_f32m8(&apps_q_old[i], vl);
                vfloat32m8_t work = __riscv_vle32_v_f32m8(&apps_work[i], vl);

                vfloat32m8_t pq_sum = __riscv_vfadd_vv_f32m8(p_old, q_old, vl);
                vfloat32m8_t half_delvc = __riscv_vfmul_vf_f32m8(delvc, 0.5f, vl);
                vfloat32m8_t term1 = __riscv_vfmul_vv_f32m8(half_delvc, pq_sum, vl);
                vfloat32m8_t half_work = __riscv_vfmul_vf_f32m8(work, 0.5f, vl);
                vfloat32m8_t e_new = __riscv_vfsub_vv_f32m8(e_old, term1, vl);
                e_new = __riscv_vfadd_vv_f32m8(e_new, half_work, vl);

                __riscv_vse32_v_f32m8(&apps_e_new[i], e_new, vl);
            }
        }

        // Second loop: compute q_new
        {
            size_t n = APPS_N1D;
            size_t vl;
            for (size_t i = 0; i < n; i += vl) {
                vl = __riscv_vsetvl_e32m8(n - i);
                vfloat32m8_t delvc = __riscv_vle32_v_f32m8(&apps_delvc[i], vl);
                vbool4_t mask_pos = __riscv_vmfgt_vf_f32m8_b4(delvc, 0.0f, vl);

                // Compute vhalf and ssc for all elements (safe even when delvc > 0)
                vfloat32m8_t compHalfStep = __riscv_vle32_v_f32m8(&apps_compHalfStep[i], vl);
                vfloat32m8_t one = __riscv_vfmv_v_f_f32m8(1.0f, vl);
                vfloat32m8_t denom = __riscv_vfadd_vv_f32m8(one, compHalfStep, vl);
                vfloat32m8_t vhalf = __riscv_vfrdiv_vf_f32m8(denom, 1.0f, vl);

                vfloat32m8_t pbvc = __riscv_vle32_v_f32m8(&apps_pbvc[i], vl);
                vfloat32m8_t e_new = __riscv_vle32_v_f32m8(&apps_e_new[i], vl);
                vfloat32m8_t bvc = __riscv_vle32_v_f32m8(&apps_bvc[i], vl);
                vfloat32m8_t pHalfStep = __riscv_vle32_v_f32m8(&apps_pHalfStep[i], vl);

                vfloat32m8_t term_a = __riscv_vfmul_vv_f32m8(pbvc, e_new, vl);
                vfloat32m8_t vhalf_sq = __riscv_vfmul_vv_f32m8(vhalf, vhalf, vl);
                vfloat32m8_t term_b = __riscv_vfmul_vv_f32m8(vhalf_sq, bvc, vl);
                term_b = __riscv_vfmul_vv_f32m8(term_b, pHalfStep, vl);
                vfloat32m8_t ssc_num = __riscv_vfadd_vv_f32m8(term_a, term_b, vl);
                vfloat32m8_t ssc = __riscv_vfdiv_vf_f32m8(ssc_num, rho0, vl);

                // Clamp ssc: if ssc <= 1.111111e-36f, ssc = 3.333333e-18f, else sqrt(ssc)
                vbool4_t mask_small = __riscv_vmfle_vf_f32m8_b4(ssc, 1.111111e-36f, vl);

                // For elements not small, compute sqrt
                vfloat32m8_t sqrt_ssc = __riscv_vfsqrt_v_f32m8(ssc, vl);

                // Merge: if small, use 3.333333e-18f, else use sqrt_ssc
                vfloat32m8_t ssc_clamped = __riscv_vfmerge_vfm_f32m8(sqrt_ssc, 3.333333e-18f, mask_small, vl);

                vfloat32m8_t ql_old = __riscv_vle32_v_f32m8(&apps_ql_old[i], vl);
                vfloat32m8_t qq_old = __riscv_vle32_v_f32m8(&apps_qq_old[i], vl);
                vfloat32m8_t q_new = __riscv_vfmul_vv_f32m8(ssc_clamped, ql_old, vl);
                q_new = __riscv_vfadd_vv_f32m8(q_new, qq_old, vl);

                // Zero out where delvc > 0
                vfloat32m8_t zero = __riscv_vfmv_v_f_f32m8(0.0f, vl);
                q_new = __riscv_vfmerge_vfm_f32m8(q_new, 0.0f, mask_pos, vl);

                __riscv_vse32_v_f32m8(&apps_q_new[i], q_new, vl);
            }
        }

        // Third loop: update e_new
        {
            size_t n = APPS_N1D;
            size_t vl;
            for (size_t i = 0; i < n; i += vl) {
                vl = __riscv_vsetvl_e32m8(n - i);
                vfloat32m8_t e_new = __riscv_vle32_v_f32m8(&apps_e_new[i], vl);
                vfloat32m8_t delvc = __riscv_vle32_v_f32m8(&apps_delvc[i], vl);
                vfloat32m8_t p_old = __riscv_vle32_v_f32m8(&apps_p_old[i], vl);
                vfloat32m8_t q_old = __riscv_vle32_v_f32m8(&apps_q_old[i], vl);
                vfloat32m8_t pHalfStep = __riscv_vle32_v_f32m8(&apps_pHalfStep[i], vl);
                vfloat32m8_t q_new = __riscv_vle32_v_f32m8(&apps_q_new[i], vl);

                vfloat32m8_t pq_old = __riscv_vfadd_vv_f32m8(p_old, q_old, vl);
                vfloat32m8_t pq_half = __riscv_vfadd_vv_f32m8(pHalfStep, q_new, vl);
                vfloat32m8_t three_pq_old = __riscv_vfmul_vf_f32m8(pq_old, 3.0f, vl);
                vfloat32m8_t four_pq_half = __riscv_vfmul_vf_f32m8(pq_half, 4.0f, vl);
                vfloat32m8_t diff = __riscv_vfsub_vv_f32m8(three_pq_old, four_pq_half, vl);
                vfloat32m8_t half_delvc = __riscv_vfmul_vf_f32m8(delvc, 0.5f, vl);
                vfloat32m8_t term = __riscv_vfmul_vv_f32m8(half_delvc, diff, vl);
                e_new = __riscv_vfadd_vv_f32m8(e_new, term, vl);

                __riscv_vse32_v_f32m8(&apps_e_new[i], e_new, vl);
            }
        }

        // Fourth loop: final e_new updates
        {
            size_t n = APPS_N1D;
            size_t vl;
            for (size_t i = 0; i < n; i += vl) {
                vl = __riscv_vsetvl_e32m8(n - i);
                vfloat32m8_t e_new = __riscv_vle32_v_f32m8(&apps_e_new[i], vl);
                vfloat32m8_t work = __riscv_vle32_v_f32m8(&apps_work[i], vl);
                vfloat32m8_t half_work = __riscv_vfmul_vf_f32m8(work, 0.5f, vl);
                e_new = __riscv_vfadd_vv_f32m8(e_new, half_work, vl);

                // ABS and clamp to 0
                vfloat32m8_t abs_e = __riscv_vfabs_v_f32m8(e_new, vl);
                vbool4_t mask_cut = __riscv_vmflt_vf_f32m8_b4(abs_e, e_cut, vl);
                e_new = __riscv_vfmerge_vfm_f32m8(e_new, 0.0f, mask_cut, vl);

                // Clamp to emin
                vbool4_t mask_emin = __riscv_vmflt_vf_f32m8_b4(e_new, emin, vl);
                e_new = __riscv_vfmerge_vfm_f32m8(e_new, emin, mask_emin, vl);

                __riscv_vse32_v_f32m8(&apps_e_new[i], e_new, vl);
            }
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] = apps_e_old[i] - 0.5f * apps_delvc[i] *
                            (apps_p_old[i] + apps_q_old[i]) + 0.5f * apps_work[i];
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            if (apps_delvc[i] > 0.0f) {
                apps_q_new[i] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[i]);
                real_t ssc = ( apps_pbvc[i] * apps_e_new[i] +
                               vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i] ) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i];
            }
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_delvc[i] *
                             ( 3.0f*(apps_p_old[i] + apps_q_old[i]) -
                               4.0f*(apps_pHalfStep[i] + apps_q_new[i]) );
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_work[i];
            if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f;
            if (apps_e_new[i] < emin)        apps_e_new[i] = emin;
        }
#endif
        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

