real_t apps_fir(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type coefflen = APPS_COEFFLEN;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
#if defined(__riscv_vector)
        // Use LMUL=4 for maximum vector parallelism
        size_t vlmax = __riscv_vsetvlmax_e32m4();

        Index_type i = 0;
        for (; i + vlmax <= APPS_N1D; i += vlmax) {
            vfloat32m4_t vsum = __riscv_vfmv_v_f_f32m4(0.0f, vlmax);

            // Unroll coefficient loop by 8 for better instruction-level parallelism
            Index_type j = 0;
            for (; j + 8 <= coefflen; j += 8) {
                vfloat32m4_t vin0 = __riscv_vle32_v_f32m4(&apps_in[i + j], vlmax);
                vfloat32m4_t vin1 = __riscv_vle32_v_f32m4(&apps_in[i + j + 1], vlmax);
                vfloat32m4_t vin2 = __riscv_vle32_v_f32m4(&apps_in[i + j + 2], vlmax);
                vfloat32m4_t vin3 = __riscv_vle32_v_f32m4(&apps_in[i + j + 3], vlmax);
                vfloat32m4_t vin4 = __riscv_vle32_v_f32m4(&apps_in[i + j + 4], vlmax);
                vfloat32m4_t vin5 = __riscv_vle32_v_f32m4(&apps_in[i + j + 5], vlmax);
                vfloat32m4_t vin6 = __riscv_vle32_v_f32m4(&apps_in[i + j + 6], vlmax);
                vfloat32m4_t vin7 = __riscv_vle32_v_f32m4(&apps_in[i + j + 7], vlmax);

                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j], vin0, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 1], vin1, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 2], vin2, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 3], vin3, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 4], vin4, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 5], vin5, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 6], vin6, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 7], vin7, vlmax);
            }

            // Handle remaining coefficients with 4-unroll
            for (; j + 4 <= coefflen; j += 4) {
                vfloat32m4_t vin0 = __riscv_vle32_v_f32m4(&apps_in[i + j], vlmax);
                vfloat32m4_t vin1 = __riscv_vle32_v_f32m4(&apps_in[i + j + 1], vlmax);
                vfloat32m4_t vin2 = __riscv_vle32_v_f32m4(&apps_in[i + j + 2], vlmax);
                vfloat32m4_t vin3 = __riscv_vle32_v_f32m4(&apps_in[i + j + 3], vlmax);

                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j], vin0, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 1], vin1, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 2], vin2, vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j + 3], vin3, vlmax);
            }

            // Handle final remaining coefficients
            for (; j < coefflen; ++j) {
                vfloat32m4_t vin = __riscv_vle32_v_f32m4(&apps_in[i + j], vlmax);
                vsum = __riscv_vfmacc_vf_f32m4(vsum, apps_coeff[j], vin, vlmax);
            }

            __riscv_vse32_v_f32m4(&apps_out[i], vsum, vlmax);
        }

        // Scalar tail handling
        for (; i < APPS_N1D; ++i) {
            real_t s = 0.0f;
            for (Index_type j = 0; j < coefflen; ++j) {
                s += apps_coeff[j] * apps_in[i + j];
            }
            apps_out[i] = s;
        }
#else
        // Scalar fallback
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t s = 0.0f;
            for (Index_type j = 0; j < coefflen; ++j) {
                s += apps_coeff[j] * apps_in[i + j];
            }
            apps_out[i] = s;
        }
#endif
        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

