real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        for (Index_type z = 0; z < num_z; ++z) {
            Index_type z_stride = z * num_m * num_g;
            Index_type z_psi_stride = z * num_d * num_g;
            for (Index_type g = 0; g < num_g; ++g) {
                Index_type phi_base = g * num_m + z_stride;
                Index_type psi_base = g * num_d + z_psi_stride;
                for (Index_type m = 0; m < num_m; ++m) {
                    real_t *phi_ptr = &lt_phidat[phi_base + m];
                    real_t sum = *phi_ptr;
                    real_t *ell_ptr = &lt_elldat[m * num_d];
                    real_t *psi_ptr = &lt_psidat[psi_base];

                    Index_type d = 0;

                    for (; d < num_d; ) {
                        size_t vl = __riscv_vsetvl_e64m1(num_d - d);
                        vfloat64m1_t v_ell = __riscv_vle64_v_f64m1((const double*)&ell_ptr[d], vl);
                        vfloat64m1_t v_psi = __riscv_vle64_v_f64m1((const double*)&psi_ptr[d], vl);
                        vfloat64m1_t v_prod = __riscv_vfmul_vv_f64m1(v_ell, v_psi, vl);
                        vfloat64m1_t v_red = __riscv_vfredusum_vs_f64m1_f64m1(v_prod, __riscv_vfmv_v_f_f64m1(0.0, 1), vl);
                        sum += __riscv_vfmv_f_s_f64m1_f64(v_red);
                        d += vl;
                    }

                    *phi_ptr = sum;
                }
            }
        }
#else
        for (Index_type z = 0; z < num_z; ++z)
        for (Index_type g = 0; g < num_g; ++g)
        for (Index_type m = 0; m < num_m; ++m)
        for (Index_type dd = 0; dd < num_d; ++dd) {
            lt_phidat[m + g * num_m + z * num_m * num_g] +=
                lt_elldat[dd + m * num_d] *
                lt_psidat[dd + g * num_d + z * num_d * num_g];
        }
#endif
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

