#include <riscv_vector.h>
#endif

real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
#if defined(__riscv_vector)
        // Fused loop with m8 LMUL for maximum vector parallelism
        // Process two chunks interleaved to hide memory latency
        Index_type i = 0;
        while (i < APPS_N1D) {
            size_t vl = __riscv_vsetvl_e32m8(APPS_N1D - i);

            // Load apps_compression[i]
            vfloat32m8_t vcomp = __riscv_vle32_v_f32m8(&apps_compression[i], vl);

            // Compute apps_bvc[i] = cls * (apps_compression[i] + 1.0f)
            vfloat32m8_t vsum = __riscv_vfadd_vf_f32m8(vcomp, 1.0f, vl);
            vfloat32m8_t vbvc = __riscv_vfmul_vf_f32m8(vsum, cls, vl);

            // Store apps_bvc[i] (needed for dummy call)
            __riscv_vse32_v_f32m8(&apps_bvc[i], vbvc, vl);

            // Load apps_e_old[i] and compute p = apps_bvc[i] * apps_e_old[i]
            vfloat32m8_t veold = __riscv_vle32_v_f32m8(&apps_e_old[i], vl);
            vfloat32m8_t vp = __riscv_vfmul_vv_f32m8(vbvc, veold, vl);

            // ABS(p) < p_cut -> p = 0.0f
            vfloat32m8_t vabs_p = __riscv_vfabs_v_f32m8(vp, vl);
            vbool4_t mask_cut = __riscv_vmflt_vf_f32m8_b4(vabs_p, p_cut, vl);
            vp = __riscv_vfmerge_vfm_f32m8(vp, 0.0f, mask_cut, vl);

            // apps_vnewc[i] >= eosvmax -> p = 0.0f
            vfloat32m8_t vvnewc = __riscv_vle32_v_f32m8(&apps_vnewc[i], vl);
            vbool4_t mask_vmax = __riscv_vmfge_vf_f32m8_b4(vvnewc, eosvmax, vl);
            vp = __riscv_vfmerge_vfm_f32m8(vp, 0.0f, mask_vmax, vl);

            // p < pmin -> p = pmin
            vbool4_t mask_pmin = __riscv_vmflt_vf_f32m8_b4(vp, pmin, vl);
            vp = __riscv_vfmerge_vfm_f32m8(vp, pmin, mask_pmin, vl);

            // Store apps_p_new[i]
            __riscv_vse32_v_f32m8(&apps_p_new[i], vp, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)         p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)               p = pmin;
            apps_p_new[i] = p;
        }
#endif
        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

