real_t apps_vol3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t vnormq = 0.0833333333333f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
#if defined(__riscv_vector)
        size_t n = APPS_N1D;
        size_t vlmax = __riscv_vsetvlmax_e32m1();
        for (size_t i = 0; i < n; ) {
            size_t vl = __riscv_vsetvl_e32m1(n - i);

            // Load x values
            vfloat32m1_t x0 = __riscv_vle32_v_f32m1(&apps_x0[i], vl);
            vfloat32m1_t x1 = __riscv_vle32_v_f32m1(&apps_x1[i], vl);
            vfloat32m1_t x2 = __riscv_vle32_v_f32m1(&apps_x2[i], vl);
            vfloat32m1_t x3 = __riscv_vle32_v_f32m1(&apps_x3[i], vl);
            vfloat32m1_t x4 = __riscv_vle32_v_f32m1(&apps_x4[i], vl);
            vfloat32m1_t x5 = __riscv_vle32_v_f32m1(&apps_x5[i], vl);
            vfloat32m1_t x6 = __riscv_vle32_v_f32m1(&apps_x6[i], vl);
            vfloat32m1_t x7 = __riscv_vle32_v_f32m1(&apps_x7[i], vl);

            // Load y values
            vfloat32m1_t y0 = __riscv_vle32_v_f32m1(&apps_y0[i], vl);
            vfloat32m1_t y1 = __riscv_vle32_v_f32m1(&apps_y1[i], vl);
            vfloat32m1_t y2 = __riscv_vle32_v_f32m1(&apps_y2[i], vl);
            vfloat32m1_t y3 = __riscv_vle32_v_f32m1(&apps_y3[i], vl);
            vfloat32m1_t y4 = __riscv_vle32_v_f32m1(&apps_y4[i], vl);
            vfloat32m1_t y5 = __riscv_vle32_v_f32m1(&apps_y5[i], vl);
            vfloat32m1_t y6 = __riscv_vle32_v_f32m1(&apps_y6[i], vl);
            vfloat32m1_t y7 = __riscv_vle32_v_f32m1(&apps_y7[i], vl);

            // Load z values
            vfloat32m1_t z0 = __riscv_vle32_v_f32m1(&apps_z0[i], vl);
            vfloat32m1_t z1 = __riscv_vle32_v_f32m1(&apps_z1[i], vl);
            vfloat32m1_t z2 = __riscv_vle32_v_f32m1(&apps_z2[i], vl);
            vfloat32m1_t z3 = __riscv_vle32_v_f32m1(&apps_z3[i], vl);
            vfloat32m1_t z4 = __riscv_vle32_v_f32m1(&apps_z4[i], vl);
            vfloat32m1_t z5 = __riscv_vle32_v_f32m1(&apps_z5[i], vl);
            vfloat32m1_t z6 = __riscv_vle32_v_f32m1(&apps_z6[i], vl);
            vfloat32m1_t z7 = __riscv_vle32_v_f32m1(&apps_z7[i], vl);

            // Compute differences
            vfloat32m1_t x71 = __riscv_vfsub_vv_f32m1(x7, x1, vl);
            vfloat32m1_t x72 = __riscv_vfsub_vv_f32m1(x7, x2, vl);
            vfloat32m1_t x74 = __riscv_vfsub_vv_f32m1(x7, x4, vl);
            vfloat32m1_t x30 = __riscv_vfsub_vv_f32m1(x3, x0, vl);
            vfloat32m1_t x50 = __riscv_vfsub_vv_f32m1(x5, x0, vl);
            vfloat32m1_t x60 = __riscv_vfsub_vv_f32m1(x6, x0, vl);

            vfloat32m1_t y71 = __riscv_vfsub_vv_f32m1(y7, y1, vl);
            vfloat32m1_t y72 = __riscv_vfsub_vv_f32m1(y7, y2, vl);
            vfloat32m1_t y74 = __riscv_vfsub_vv_f32m1(y7, y4, vl);
            vfloat32m1_t y30 = __riscv_vfsub_vv_f32m1(y3, y0, vl);
            vfloat32m1_t y50 = __riscv_vfsub_vv_f32m1(y5, y0, vl);
            vfloat32m1_t y60 = __riscv_vfsub_vv_f32m1(y6, y0, vl);

            vfloat32m1_t z71 = __riscv_vfsub_vv_f32m1(z7, z1, vl);
            vfloat32m1_t z72 = __riscv_vfsub_vv_f32m1(z7, z2, vl);
            vfloat32m1_t z74 = __riscv_vfsub_vv_f32m1(z7, z4, vl);
            vfloat32m1_t z30 = __riscv_vfsub_vv_f32m1(z3, z0, vl);
            vfloat32m1_t z50 = __riscv_vfsub_vv_f32m1(z5, z0, vl);
            vfloat32m1_t z60 = __riscv_vfsub_vv_f32m1(z6, z0, vl);

            // First term
            vfloat32m1_t xps = __riscv_vfadd_vv_f32m1(x71, x60, vl);
            vfloat32m1_t yps = __riscv_vfadd_vv_f32m1(y71, y60, vl);
            vfloat32m1_t zps = __riscv_vfadd_vv_f32m1(z71, z60, vl);

            vfloat32m1_t cyz = __riscv_vfmsub_vv_f32m1(y72, z30, __riscv_vfmul_vv_f32m1(z72, y30, vl), vl);
            vfloat32m1_t czx = __riscv_vfmsub_vv_f32m1(z72, x30, __riscv_vfmul_vv_f32m1(x72, z30, vl), vl);
            vfloat32m1_t cxy = __riscv_vfmsub_vv_f32m1(x72, y30, __riscv_vfmul_vv_f32m1(y72, x30, vl), vl);

            vfloat32m1_t v = __riscv_vfmacc_vv_f32m1(__riscv_vfmacc_vv_f32m1(__riscv_vfmul_vv_f32m1(xps, cyz, vl), yps, czx, vl), zps, cxy, vl);

            // Second term
            xps = __riscv_vfadd_vv_f32m1(x72, x50, vl);
            yps = __riscv_vfadd_vv_f32m1(y72, y50, vl);
            zps = __riscv_vfadd_vv_f32m1(z72, z50, vl);

            cyz = __riscv_vfmsub_vv_f32m1(y74, z60, __riscv_vfmul_vv_f32m1(z74, y60, vl), vl);
            czx = __riscv_vfmsub_vv_f32m1(z74, x60, __riscv_vfmul_vv_f32m1(x74, z60, vl), vl);
            cxy = __riscv_vfmsub_vv_f32m1(x74, y60, __riscv_vfmul_vv_f32m1(y74, x60, vl), vl);

            v = __riscv_vfmacc_vv_f32m1(__riscv_vfmacc_vv_f32m1(__riscv_vfmacc_vv_f32m1(v, xps, cyz, vl), yps, czx, vl), zps, cxy, vl);

            // Third term
            xps = __riscv_vfadd_vv_f32m1(x74, x30, vl);
            yps = __riscv_vfadd_vv_f32m1(y74, y30, vl);
            zps = __riscv_vfadd_vv_f32m1(z74, z30, vl);

            cyz = __riscv_vfmsub_vv_f32m1(y71, z50, __riscv_vfmul_vv_f32m1(z71, y50, vl), vl);
            czx = __riscv_vfmsub_vv_f32m1(z71, x50, __riscv_vfmul_vv_f32m1(x71, z50, vl), vl);
            cxy = __riscv_vfmsub_vv_f32m1(x71, y50, __riscv_vfmul_vv_f32m1(y71, x50, vl), vl);

            v = __riscv_vfmacc_vv_f32m1(__riscv_vfmacc_vv_f32m1(__riscv_vfmacc_vv_f32m1(v, xps, cyz, vl), yps, czx, vl), zps, cxy, vl);

            // Multiply by vnormq
            vfloat32m1_t vnormq_vec = __riscv_vfmv_v_f_f32m1(vnormq, vl);
            v = __riscv_vfmul_vv_f32m1(v, vnormq_vec, vl);

            // Store result
            __riscv_vse32_v_f32m1(&apps_vol[i], v, vl);

            i += vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t x71 = apps_x7[i] - apps_x1[i], x72 = apps_x7[i] - apps_x2[i], x74 = apps_x7[i] - apps_x4[i];
            real_t x30 = apps_x3[i] - apps_x0[i], x50 = apps_x5[i] - apps_x0[i], x60 = apps_x6[i] - apps_x0[i];
            real_t y71 = apps_y7[i] - apps_y1[i], y72 = apps_y7[i] - apps_y2[i], y74 = apps_y7[i] - apps_y4[i];
            real_t y30 = apps_y3[i] - apps_y0[i], y50 = apps_y5[i] - apps_y0[i], y60 = apps_y6[i] - apps_y0[i];
            real_t z71 = apps_z7[i] - apps_z1[i], z72 = apps_z7[i] - apps_z2[i], z74 = apps_z7[i] - apps_z4[i];
            real_t z30 = apps_z3[i] - apps_z0[i], z50 = apps_z5[i] - apps_z0[i], z60 = apps_z6[i] - apps_z0[i];
            real_t xps = x71 + x60, yps = y71 + y60, zps = z71 + z60;
            real_t cyz = y72*z30 - z72*y30, czx = z72*x30 - x72*z30, cxy = x72*y30 - y72*x30;
            real_t v = xps*cyz + yps*czx + zps*cxy;
            xps = x72 + x50; yps = y72 + y50; zps = z72 + z50;
            cyz = y74*z60 - z74*y60; czx = z74*x60 - x74*z60; cxy = x74*y60 - y74*x60;
            v += xps*cyz + yps*czx + zps*cxy;
            xps = x74 + x30; yps = y74 + y30; zps = z74 + z30;
            cyz = y71*z50 - z71*y50; czx = z71*x50 - x71*z50; cxy = x71*y50 - y71*x50;
            v += xps*cyz + yps*czx + zps*cxy;
            apps_vol[i] = v * vnormq;
        }
#endif
        dummy(apps_vol, NULL, NULL, NULL, NULL, vnormq);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

