    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;
        size_t vlmax = __riscv_vsetvlmax_e32m2();
        for (; i + vlmax <= LEN_1D; i += vlmax) {
