real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;

    real_t y_diff = ypoint - yp;
    real_t y_diff_sq = y_diff * y_diff;
    real_t one = 1.0;
    real_t half = 0.5;

    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = 0.0;

#if defined(__riscv_vector)
        size_t n = LEN_1D;
        size_t vlmax = __riscv_vsetvlmax_e64m1();

        // Precompute constants for vectorized x0 + i*h
        // We'll use a strip-mining approach with vector of indices

        for (size_t i = 0; i < n; ) {
            size_t vl = __riscv_vsetvl_e64m1(n - i);

            // Create vector of indices: i, i+1, i+2, ...
            vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
            // Convert to double
            vfloat64m1_t vidx_f = __riscv_vfcvt_f_xu_v_f64m1(vidx, vl);

            // Add base offset i
            vfloat64m1_t vindices = __riscv_vfadd_vf_f64m1(vidx_f, (double)i, vl);

            // xv = x0 + indices * h
            vfloat64m1_t vxv = __riscv_vfmadd_vv_f64m1(vindices, __riscv_vfmv_v_f_f64m1(h, vl), __riscv_vfmv_v_f_f64m1(x0, vl), vl);

