            vfloat64m1_t vdiff = __riscv_vfsub_vf_f64m1(vxv, half, vl);
            // (xv - 0.5)^2
            vfloat64m1_t vdiff_sq = __riscv_vfmul_vv_f64m1(vdiff, vdiff, vl);

            // denom = (xv - 0.5)^2 + y_diff_sq
            vfloat64m1_t vdenom = __riscv_vfadd_vf_f64m1(vdiff_sq, y_diff_sq, vl);

            // denom + 1.0
            vfloat64m1_t varg = __riscv_vfadd_vf_f64m1(vdenom, one, vl);

            // sqrt(denom + 1.0)
            vfloat64m1_t vsqrt = __riscv_vfsqrt_v_f64m1(varg, vl);

            // 1.0 / sqrt(...)
            vfloat64m1_t vrecip = __riscv_vfrdiv_vf_f64m1(vsqrt, one, vl);

