            sumx += __riscv_vfmv_f_s_f64m1_f64(__riscv_vfredusum_vs_f64m1_f64m1(vrecip, __riscv_vfmv_s_f_f64m1(0.0, vlmax), vl));

            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = x0 + i*h;
            real_t denom = (xv - 0.5)*(xv - 0.5) + (ypoint - yp)*(ypoint - yp);
            sumx += 1.0f / sqrtf(denom + 1.0f);
        }
#endif
        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

