real_t lcals_eos(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t r = 0.5, t = 0.25, q = 0.125;

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;
        size_t vlmax = __riscv_vsetvlmax_e32m2();

        // Precompute common coefficients
        real_t r2 = r * r;        // 0.25
        real_t t2 = t * t;        // 0.0625
        real_t q2 = q * q;        // 0.015625

        // Broadcast scalars to vectors
        vfloat32m2_t v_r = __riscv_vfmv_v_f_f32m2(r, vlmax);
        vfloat32m2_t v_t = __riscv_vfmv_v_f_f32m2(t, vlmax);
        vfloat32m2_t v_q = __riscv_vfmv_v_f_f32m2(q, vlmax);
        vfloat32m2_t v_r2 = __riscv_vfmv_v_f_f32m2(r2, vlmax);
        vfloat32m2_t v_t2 = __riscv_vfmv_v_f_f32m2(t2, vlmax);
        vfloat32m2_t v_q2 = __riscv_vfmv_v_f_f32m2(q2, vlmax);

        for (; i + vlmax <= LEN_1D - 6; i += vlmax) {
            // Load u[i], u[i+1], u[i+2], u[i+3], u[i+4], u[i+5], u[i+6]
            vfloat32m2_t v_u_i = __riscv_vle32_v_f32m2(&u[i], vlmax);
            vfloat32m2_t v_u_i1 = __riscv_vle32_v_f32m2(&u[i+1], vlmax);
            vfloat32m2_t v_u_i2 = __riscv_vle32_v_f32m2(&u[i+2], vlmax);
            vfloat32m2_t v_u_i3 = __riscv_vle32_v_f32m2(&u[i+3], vlmax);
            vfloat32m2_t v_u_i4 = __riscv_vle32_v_f32m2(&u[i+4], vlmax);
            vfloat32m2_t v_u_i5 = __riscv_vle32_v_f32m2(&u[i+5], vlmax);
            vfloat32m2_t v_u_i6 = __riscv_vle32_v_f32m2(&u[i+6], vlmax);

            // Load z[i], y[i]
            vfloat32m2_t v_z_i = __riscv_vle32_v_f32m2(&z[i], vlmax);
            vfloat32m2_t v_y_i = __riscv_vle32_v_f32m2(&y[i], vlmax);

            // Compute inner terms with FMA chains
            // term1 = z[i] + r*y[i]
            vfloat32m2_t v_term1 = __riscv_vfmadd(v_y_i, v_r, v_z_i, vlmax);

            // term2_inner = u[i+2] + r*u[i+1]
            vfloat32m2_t v_term2_inner = __riscv_vfmadd(v_u_i1, v_r, v_u_i2, vlmax);
            // term2 = u[i+3] + r*term2_inner
            vfloat32m2_t v_term2 = __riscv_vfmadd(v_term2_inner, v_r, v_u_i3, vlmax);

            // term3_inner = u[i+5] + q*u[i+4]
            vfloat32m2_t v_term3_inner = __riscv_vfmadd(v_u_i4, v_q, v_u_i5, vlmax);
            // term3 = u[i+6] + q*term3_inner
            vfloat32m2_t v_term3 = __riscv_vfmadd(v_term3_inner, v_q, v_u_i6, vlmax);

            // Assemble full expression:
            // x[i] = u[i] + r*term1 + t*term2 + t2*term3

            // Start with u[i] + r*term1
            vfloat32m2_t v_result = __riscv_vfmadd(v_term1, v_r, v_u_i, vlmax);
            // Add t*term2
            v_result = __riscv_vfmadd(v_term2, v_t, v_result, vlmax);
            // Add t2*term3
            v_result = __riscv_vfmadd(v_term3, v_t2, v_result, vlmax);

            __riscv_vse32_v_f32m2(&x[i], v_result, vlmax);
        }

        // Scalar tail
        for (; i < LEN_1D - 6; ++i) {
            x[i] = u[i] + r*( z[i] + r*y[i] ) +
                          t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) +
                             t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) ) );
        }
#else
        for (Index_type i = 0; i < LEN_1D - 6; ++i) {
            x[i] = u[i] + r*( z[i] + r*y[i] ) +
                          t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) +
                             t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) ) );
        }
#endif
        dummy(x, u, y, z, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

