real_t lcals_first_min(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type loc = 0;
    real_t mn = x[0];
    for (int nl = 0; nl < iterations; nl++) {
        loc = 0; mn = x[0];
#if defined(__riscv_vector)
        size_t vlmax = __riscv_vsetvlmax_e32m1();
        vfloat32m1_t vmn = __riscv_vfmv_v_f_f32m1(mn, vlmax);
        vuint32m1_t vloc = __riscv_vmv_v_x_u32m1(0, vlmax);
        vuint32m1_t vidx_base = __riscv_vid_v_u32m1(vlmax);

        size_t n = LEN_1D;
        size_t i = 0;
        while (n > 0) {
            size_t vl = __riscv_vsetvl_e32m1(n);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[i], vl);
            vbool32_t mask = __riscv_vmflt_vv_f32m1_b32(vx, vmn, vl);

            if (__riscv_vfirst_m_b32(mask, vl) >= 0) {
                vmn = __riscv_vfmerge_vfm_f32m1(vmn, vx, mask, vl);
                vuint32m1_t vidx = __riscv_vadd_vx_u32m1(vidx_base, (uint32_t)i, vl);
                vloc = __riscv_vmerge_vxm_u32m1(vloc, vidx, mask, vl);
            }

            i += vl;
            n -= vl;
        }

        // Reduce vector minimum to scalar
        vfloat32m1_t vred = __riscv_vfredmin_vs_f32m1_f32m1(vmn, __riscv_vfmv_s_f_f32m1(INFINITY, 1), vlmax);
        real_t vec_mn = __riscv_vfmv_f_s_f32m1_f32(vred);

        // Find first position where minimum occurs
        n = LEN_1D;
        i = 0;
        Index_type vec_loc = LEN_1D;
        while (n > 0) {
            size_t vl = __riscv_vsetvl_e32m1(n);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[i], vl);
            vbool32_t mask = __riscv_vmfeq_vv_f32m1_b32(vx, vred, vl);

            int first = __riscv_vfirst_m_b32(mask, vl);
            if (first >= 0) {
                vec_loc = (Index_type)(i + first);
                break;
            }

            i += vl;
            n -= vl;
        }

        if (vec_mn < mn) {
            mn = vec_mn;
            loc = vec_loc;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < mn) { mn = x[i]; loc = i; }
        }
#endif
        dummy(x, NULL, NULL, NULL, NULL, mn);
    }
    y[0] = mn;
    y[1] = (real_t)loc / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

