real_t lcals_first_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        size_t n = LEN_1D - 1;
        // Use unit-stride segment load to load consecutive pairs, or use widening approach
        // Process with maximum vector length for better amortization
        size_t vlmax = __riscv_vsetvlmax_e32m8();

        // Peel off first element to handle alignment and enable larger vectors
        // Actually, let's use a different strategy: process in chunks with vle32

        size_t i = 0;
