        while (n > 0) {
            size_t vl = __riscv_vsetvl_e32m4(n);
            // Load y[i] and y[i+1] with float (real_t) type
            vfloat32m4_t vy_prev = __riscv_vle32_v_f32m4(&y[i], vl);
            vfloat32m4_t vy_curr = __riscv_vle32_v_f32m4(&y[i + 1], vl);
            // Compute x[i+1] = y[i] + y[i+1]
            vfloat32m4_t vsum = __riscv_vfadd_vv_f32m4(vy_prev, vy_curr, vl);
            __riscv_vse32_v_f32m4(&x[i + 1], vsum, vl);
