real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;
        size_t vlmax = __riscv_vsetvlmax_e32m1();
        // Use larger LMUL for better throughput on memory-bound operations
        size_t vlmax_m2 = __riscv_vsetvlmax_e32m2();
        for (; i + vlmax_m2 <= LEN_1D; i += vlmax_m2) {
            vfloat32m2_t vu = __riscv_vle32_v_f32m2(&u[i], vlmax_m2);
            vfloat32m2_t vv = __riscv_vle32_v_f32m2(&v[i], vlmax_m2);
            vfloat32m2_t vx = __riscv_vle32_v_f32m2(&x[i], vlmax_m2);

            // y[i] = u[i] / v[i]
            vfloat32m2_t vy = __riscv_vfdiv_vv_f32m2(vu, vv, vlmax_m2);
            __riscv_vse32_v_f32m2(&y[i], vy, vlmax_m2);

            // Process expf with scalar fallback - but use LMUL=1 for extraction
            // Split into two LMUL=1 chunks for better extraction efficiency
            size_t half = vlmax_m2 / 2;
            vfloat32m1_t vy_lo = __riscv_vlmul_trunc_v_f32m2_f32m1(vy);
            vfloat32m1_t vy_hi = __riscv_vslidedown_vx_f32m2(vy, half, vlmax_m2);
            vy_hi = __riscv_vlmul_trunc_v_f32m2_f32m1(vy_hi);

            vfloat32m1_t vx_lo = __riscv_vlmul_trunc_v_f32m2_f32m1(vx);
            vfloat32m1_t vx_hi = __riscv_vslidedown_vx_f32m2(vx, half, vlmax_m2);
            vx_hi = __riscv_vlmul_trunc_v_f32m2_f32m1(vx_hi);

            // Process first half
            for (size_t j = 0; j < vlmax; j++) {
                float yj = __riscv_vfmv_f_s_f32m1_f32(__riscv_vslidedown_vx_f32m1(vy_lo, j, vlmax));
                float ey = expf(yj) - 1.0f;
                float xj = __riscv_vfmv_f_s_f32m1_f32(__riscv_vslidedown_vx_f32m1(vx_lo, j, vlmax));
                w[i + j] = xj / ey;
            }
            // Process second half
            for (size_t j = 0; j < vlmax && (half + j) < vlmax_m2; j++) {
                float yj = __riscv_vfmv_f_s_f32m1_f32(__riscv_vslidedown_vx_f32m1(vy_hi, j, vlmax));
                float ey = expf(yj) - 1.0f;
                float xj = __riscv_vfmv_f_s_f32m1_f32(__riscv_vslidedown_vx_f32m1(vx_hi, j, vlmax));
                w[i + half + j] = xj / ey;
            }
        }
        // Handle remaining elements with scalar code
        for (; i < LEN_1D; ++i) {
            y[i] = u[i] / v[i];
            w[i] = x[i] / ( expf(y[i]) - 1.0f );
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = u[i] / v[i];
            w[i] = x[i] / ( expf(y[i]) - 1.0f );
        }
#endif
        dummy(y, w, u, v, x, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

