    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        // Vectorized tridiagonal elimination
        // xout[i] = z[i] * (y[i] - xin[i-1]) for i = 1 to LEN_1D-1

        // Use LMUL=1 for better register pressure and cache utilization
